package com.focuscoins.app;

import android.app.*; import android.app.admin.DevicePolicyManager; import android.app.usage.*; import android.content.*; import android.graphics.Color; import android.graphics.PixelFormat; import android.graphics.drawable.GradientDrawable; import android.os.*; import android.provider.Settings; import android.text.*; import android.view.*; import android.widget.*; import java.time.*; import java.util.*;

public class FocusService extends Service {
 public static final String ACTION_LOCK="com.focuscoins.LOCK",ACTION_HOME="com.focuscoins.HOME",ACTION_SESSION="com.focuscoins.SESSION",ACTION_FOREGROUND="com.focuscoins.FOREGROUND";
 private static final String CHANNEL="focus_running",STATE="service_running",SESSIONS="focus_active_sessions"; private Ledger ledger; private SharedPreferences sessionPrefs; private boolean screenOn; private View overlay,coinBadge,dailyIsland; private String foreground="",sessionPackage="",cancelledPackage=""; private long sessionEnds,lastAppCheck,lastUnlockPrompt,cancelledUntil; private int shownCoins=Integer.MIN_VALUE; private final Map<String,Long> authorizedUntil=new HashMap<>();
 private final Handler handler=new Handler(Looper.getMainLooper());
 public static final Set<String> FIXED_FREE=Collections.unmodifiableSet(new HashSet<>(Arrays.asList("com.android.dialer","com.google.android.dialer","com.android.incallui","com.android.mms","com.google.android.apps.messaging","com.android.contacts","com.google.android.contacts","com.android.settings","com.android.systemui","miui.systemui.plugin","com.android.systemui.accessibility.accessibilitymenu","com.miui.systemui.devices.overlay","com.miui.securitycenter","com.miui.securityadd","com.miui.contentextension","com.xiaomi.scanner","com.android.quicksearchbox","com.google.android.googlequicksearchbox","com.miui.personalassistant","com.miui.voiceassist","com.miui.misound","com.miui.aod","com.miui.wallpaper","com.xiaomi.misubscreenui","com.miui.notes","com.google.android.keep","com.miui.calculator","com.android.calculator2","com.android.soundrecorder","com.google.android.apps.recorder","com.android.calendar","com.google.android.calendar","com.android.deskclock","com.google.android.deskclock","com.android.camera","com.android.fileexplorer","com.google.android.documentsui","com.android.providers.downloads","com.android.providers.downloads.ui","com.autonavi.minimap","com.baidu.BaiduMap","com.android.settings.intelligence","com.google.android.apps.safetyhub","com.miui.weather2","com.coloros.weather2","com.huawei.android.totemweather","com.google.android.apps.weather","com.google.android.apps.healthdata")));
 public static final Set<String> FIXED_LIMITED=Collections.unmodifiableSet(new HashSet<>(Arrays.asList("com.ss.android.ugc.aweme","com.ss.android.ugc.aweme.lite","com.smile.gifmaker","com.kuaishou.nebula","com.xingin.xhs","com.phoenix.read","com.dragon.read","com.kmxs.reader","com.qidian.QDReader","com.kuaikan.comic","com.bilibili.comic","com.tencent.tmgp.sgame","com.tencent.tmgp.pubgmhd","com.miHoYo.Yuanshen","com.tencent.tmgp.party","air.tv.douyu.android","com.duowan.kiwi","tv.danmaku.bili","com.tencent.qqlive","com.qiyi.video","com.youku.phone","com.hunantv.imgo.activity","com.netflix.mediaclient","com.google.android.youtube","com.sina.weibo","com.zhihu.android","com.baidu.tieba","com.ximalaya.ting.android","com.ss.android.article.news","com.taobao.taobao","com.xunmeng.pinduoduo","com.shizhuang.duapp","com.taobao.idlefish")));
 private long lastNotificationRefresh;
 private final Runnable pulse=new Runnable(){public void run(){long now=System.currentTimeMillis();ledger.tick(screenOn,now);updateNotification();if(screenOn){checkForeground(now);if(!sessionPackage.isEmpty()&&sessionPackage.equals(foreground)&&now>=sessionEnds&&overlay==null)showExpired();}handler.postDelayed(this,1000);}};
 private final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){ledger.tick(screenOn,System.currentTimeMillis());if(Intent.ACTION_SCREEN_ON.equals(i.getAction()))screenOn=true;if(Intent.ACTION_USER_PRESENT.equals(i.getAction())){screenOn=true;foreground="";lastAppCheck=0;boolean summary=showDailyIsland();handler.postDelayed(()->showUnlockPrompt(),summary?6800:350);}if(Intent.ACTION_SCREEN_OFF.equals(i.getAction())){screenOn=false;foreground="";endSession();}}};
 public static void start(Context c){if(Build.VERSION.SDK_INT>=26)c.startForegroundService(new Intent(c,FocusService.class));else c.startService(new Intent(c,FocusService.class));} public static boolean isRunning(Context c){return c.getSharedPreferences(MainActivity.PREFS,0).getBoolean(STATE,false);}
 @Override public void onCreate(){super.onCreate();getSharedPreferences(MainActivity.PREFS,0).edit().putBoolean(STATE,true).apply();sessionPrefs=getSharedPreferences(SESSIONS,0);ledger=new Ledger(this);screenOn=((PowerManager)getSystemService(POWER_SERVICE)).isInteractive();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"金币常驻显示",NotificationManager.IMPORTANCE_LOW));startForeground(7,notification());IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_SCREEN_ON);f.addAction(Intent.ACTION_SCREEN_OFF);f.addAction(Intent.ACTION_USER_PRESENT);registerReceiver(receiver,f);showCoinBadge();handler.post(pulse);}
 private Notification notification(){PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);int coins=ledger==null?0:ledger.coins();shownCoins=coins;Notification.Builder b=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("现有金币："+coins).setContentText("专注保护正在运行").setOngoing(true).setAutoCancel(false).setCategory(Notification.CATEGORY_SERVICE).setOnlyAlertOnce(true).setContentIntent(pi);if(Build.VERSION.SDK_INT>=31)b.setForegroundServiceBehavior(Notification.FOREGROUND_SERVICE_IMMEDIATE);Notification n=b.build();n.flags|=Notification.FLAG_ONGOING_EVENT|Notification.FLAG_NO_CLEAR;return n;}
 private void updateNotification(){int now=ledger.coins();long time=System.currentTimeMillis();if(now!=shownCoins||time-lastNotificationRefresh>=3000){getSystemService(NotificationManager.class).notify(7,notification());lastNotificationRefresh=time;}if(coinBadge instanceof TextView)((TextView)coinBadge).setText("🪙 "+now);}
 private void showCoinBadge(){if(!Settings.canDrawOverlays(this)||coinBadge!=null)return;TextView badge=label("🪙 "+ledger.coins(),14,Color.WHITE);badge.setPadding(14,4,14,4);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.argb(220,35,45,40));bg.setCornerRadius(24);badge.setBackground(bg);WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;p.x=0;p.y=4;if(Build.VERSION.SDK_INT>=28)p.layoutInDisplayCutoutMode=WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_ALWAYS;getSystemService(WindowManager.class).addView(badge,p);coinBadge=badge;}
 private boolean showDailyIsland(){if(!Settings.canDrawOverlays(this)||dailyIsland!=null)return false;org.json.JSONObject summary=ledger.pendingDailySummary();if(summary==null)return false;TextView island=label("🌹 "+summary.optInt("roses")+" 朵  ·  "+formatMinutes(summary.optInt("screenMinutes"))+"\n"+summary.optString("item"),15,Color.WHITE);island.setGravity(Gravity.CENTER);island.setMaxLines(3);island.setPadding(28,18,28,18);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.argb(238,18,35,33));bg.setCornerRadius(48);island.setBackground(bg);int width=(int)(getResources().getDisplayMetrics().density*340);WindowManager.LayoutParams p=new WindowManager.LayoutParams(width,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;p.y=110;WindowManager wm=getSystemService(WindowManager.class);wm.addView(island,p);dailyIsland=island;ledger.markDailySummaryShown(summary.optString("day"));handler.postDelayed(()->{if(dailyIsland==island){try{wm.removeView(island);}catch(Exception ignored){}dailyIsland=null;}},6200);return true;} private String formatMinutes(int minutes){return minutes/60+" 小时 "+minutes%60+" 分钟";}
 private void showUnlockPrompt(){long now=System.currentTimeMillis();if(!screenOn||overlay!=null||now-lastUnlockPrompt<3000||!Settings.canDrawOverlays(this))return;lastUnlockPrompt=now;WindowManager wm=getSystemService(WindowManager.class);LinearLayout card=baseCard();card.addView(label("这次拿起手机，要完成什么？",29,Color.rgb(13,42,40)));card.addView(label("先说清目的，再开始使用",16,Color.rgb(91,117,112)));EditText purpose=styledField("写下这次使用目的",2);card.addView(purpose);EditText minutes=minuteInput();card.addView(minutes);Button go=new Button(this);go.setText("开始专注");stylePrimary(go);go.setOnClickListener(v->{String s=purpose.getText().toString().trim();int m=parseMinutes(minutes);if(s.isEmpty()){purpose.setError("请先填写目的");return;}if(m<1){minutes.setError("请输入 1–1440 分钟");return;}ledger.record("解锁意图",m+" 分钟 · "+s);removeOverlay(wm,card);foreground="";lastAppCheck=0;});card.addView(go);addOverlay(wm,card);}
 private EditText minuteInput(){EditText v=new EditText(this);v.setHint("预计使用分钟数");v.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(24);v.setBackground(bg);v.setPadding(24,16,24,16);return v;} private int parseMinutes(EditText v){try{int n=Integer.parseInt(v.getText().toString().trim());return n>=1&&n<=1440?n:-1;}catch(Exception e){return-1;}}
 private void acceptForeground(String pkg){if(pkg==null||isInputMethod(pkg))return;long now=System.currentTimeMillis();if(pkg.equals(getPackageName())||isHome(pkg)){foreground="";sessionPackage="";sessionEnds=0;return;}long allowed=authorizedUntil.containsKey(pkg)?authorizedUntil.get(pkg):sessionPrefs.getLong(pkg,0);if(allowed>now){authorizedUntil.put(pkg,allowed);foreground=pkg;sessionPackage=pkg;sessionEnds=allowed;return;}if(allowed>0){authorizedUntil.remove(pkg);sessionPrefs.edit().remove(pkg).apply();}if(pkg.equals(cancelledPackage)&&now<cancelledUntil)return;if(!pkg.equals(cancelledPackage)){cancelledPackage="";cancelledUntil=0;}if(pkg.equals("com.android.systemui")||overlay!=null)return;if(pkg.equals(foreground))return;foreground=pkg;sessionPackage="";sessionEnds=0;showEntry(pkg);}
 private void checkForeground(long now){if(now-lastAppCheck<700||overlay!=null)return;lastAppCheck=now;UsageStatsManager u=(UsageStatsManager)getSystemService(USAGE_STATS_SERVICE);UsageEvents ev=u.queryEvents(now-60_000,now);UsageEvents.Event e=new UsageEvents.Event();String latest=null;long t=0;while(ev.hasNextEvent()){ev.getNextEvent(e);if((e.getEventType()==UsageEvents.Event.ACTIVITY_RESUMED||e.getEventType()==UsageEvents.Event.MOVE_TO_FOREGROUND)&&e.getTimeStamp()>t){latest=e.getPackageName();t=e.getTimeStamp();}}if(latest==null){SortedMap<Long,UsageStats> stats=new TreeMap<>();for(UsageStats s:u.queryUsageStats(UsageStatsManager.INTERVAL_DAILY,now-60_000,now))if(s.getLastTimeUsed()>0)stats.put(s.getLastTimeUsed(),s);if(!stats.isEmpty())latest=stats.get(stats.lastKey()).getPackageName();}acceptForeground(latest);}
 private boolean isFree(String pkg){return FIXED_FREE.contains(pkg)||getSharedPreferences(MainActivity.PREFS,0).getStringSet(MainActivity.CUSTOM_FREE,Collections.emptySet()).contains(pkg);}
 private boolean isLimited(String pkg){if(isFree(pkg))return false;if(FIXED_LIMITED.contains(pkg))return true;return getSharedPreferences(MainActivity.PREFS,0).getStringSet(MainActivity.CUSTOM_LIMITED,Collections.emptySet()).contains(pkg);}
 private void showEntry(String pkg){if(isFree(pkg))return;String name=appName(pkg);if(!Settings.canDrawOverlays(this)){goHome();startActivity(new Intent(this,CheckInActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP).putExtra("pkg",pkg).putExtra("app",name).putExtra("limited",isLimited(pkg)));return;}showEntryOverlay(pkg,name,isLimited(pkg));}
 private void showEntryOverlay(String pkg,String name,boolean limited){WindowManager wm=getSystemService(WindowManager.class);LinearLayout card=baseCard();card.addView(label("打开 "+name,29,Color.rgb(13,42,40)));card.addView(label(limited?"写下目的和时间，投入金币后开始":"写下目的和时间，本应用不投入金币",16,Color.rgb(91,117,112)));EditText purpose=styledField("这次打开要做什么？",2);card.addView(purpose);EditText duration=minuteInput();card.addView(duration);TextView price=label("",16,Color.rgb(0,116,105));card.addView(price);Runnable refresh=()->{int m=parseMinutes(duration);price.setText(m<1?"请输入预计分钟数":limited?"需投入 "+cost(m)+" 金币  ·  当前 "+ledger.coins():"免费使用  ·  当前 "+ledger.coins()+" 金币");};duration.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});refresh.run();Button begin=new Button(this);begin.setText("开始使用");stylePrimary(begin);begin.setOnClickListener(v->{String s=purpose.getText().toString().trim();int m=parseMinutes(duration);if(s.isEmpty()){purpose.setError("请先填写目的");return;}if(m<1){duration.setError("请输入 1–1440 分钟");return;}int charge=limited?cost(m):0;if(charge>0&&!ledger.spend(charge,name,m)){price.setText("金币不足，需要 "+charge+"，当前只有 "+ledger.coins());return;}if(charge==0)ledger.record("使用登记",name+" · "+m+" 分钟 · "+s+" · 免费");else ledger.record("使用目的",name+" · "+s);startSession(pkg,m);removeOverlay(wm,card);});card.addView(begin);Button leave=new Button(this);leave.setText("取消并回到主屏幕");styleSecondary(leave);leave.setOnClickListener(v->{cancelledPackage=pkg;cancelledUntil=System.currentTimeMillis()+4000;removeOverlay(wm,card);goHome();});LinearLayout.LayoutParams leaveParams=new LinearLayout.LayoutParams(-1,112);leaveParams.setMargins(0,20,0,0);card.addView(leave,leaveParams);addOverlay(wm,card);}
 private int cost(int minutes){ZonedDateTime z=Instant.now().atZone(ZoneId.systemDefault());boolean night=z.getHour()>=23||z.getHour()<7;return minutes*(night?Ledger.NIGHT_COST_PER_MIN:Ledger.COST_PER_MIN);}
 private void showExpired(){String pkg=sessionPackage,name=appName(pkg);authorizedUntil.remove(pkg);sessionPrefs.edit().remove(pkg).apply();WindowManager wm=getSystemService(WindowManager.class);LinearLayout card=baseCard();card.addView(label(name+" 的预计时间已到",28,Color.rgb(20,23,28)));card.addView(label("请选择现在要做什么。继续使用会重新填写目的、预计时间并再次投入金币。",16,Color.DKGRAY));Button lock=new Button(this);lock.setText("锁屏");lock.setOnClickListener(v->{ledger.record("到时结束",name+" · 锁屏");removeOverlay(wm,card);endSession();lock();});card.addView(lock);Button home=new Button(this);home.setText("回到主屏幕");home.setOnClickListener(v->{ledger.record("到时结束",name+" · 回到主屏幕");removeOverlay(wm,card);endSession();goHome();});card.addView(home);Button again=new Button(this);again.setText("继续使用（重新登记）");again.setOnClickListener(v->{removeOverlay(wm,card);endSession();showEntryOverlay(pkg,name,isLimited(pkg));});card.addView(again);addOverlay(wm,card);}
 private LinearLayout baseCard(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(56,92,56,56);c.setBackgroundColor(Color.rgb(239,248,246));return c;} private TextView label(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,12,0,12);return v;} private EditText styledField(String hint,int lines){EditText v=minuteInput();v.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);v.setHint(hint);v.setMinLines(lines);return v;} private void stylePrimary(Button b){b.setTextColor(Color.WHITE);b.setTextSize(17);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{Color.rgb(0,143,128),Color.rgb(0,116,105)});g.setCornerRadius(28);b.setBackground(g);b.setMinHeight(112);} private void styleSecondary(Button b){b.setTextColor(Color.rgb(0,116,105));b.setTextSize(17);GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(28);g.setStroke(3,Color.rgb(0,143,128));b.setBackground(g);b.setMinHeight(112);}
 private void addOverlay(WindowManager wm,View card){WindowManager.LayoutParams p=new WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS|WindowManager.LayoutParams.FLAG_FULLSCREEN,PixelFormat.TRANSLUCENT);if(Build.VERSION.SDK_INT>=28)p.layoutInDisplayCutoutMode=WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_ALWAYS;wm.addView(card,p);overlay=card;} private void removeOverlay(WindowManager wm,View card){try{wm.removeView(card);}catch(Exception ignored){}if(overlay==card)overlay=null;}
 private void startSession(String pkg,int minutes){sessionPackage=pkg;sessionEnds=System.currentTimeMillis()+minutes*60_000L;authorizedUntil.put(pkg,sessionEnds);sessionPrefs.edit().putLong(pkg,sessionEnds).apply();foreground=pkg;} private void endSession(){sessionPackage="";sessionEnds=0;}
 private void goHome(){startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));foreground="";} private boolean isHome(String pkg){Intent i=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME);android.content.pm.ResolveInfo r=getPackageManager().resolveActivity(i,0);return r!=null&&r.activityInfo!=null&&pkg.equals(r.activityInfo.packageName);} private boolean isInputMethod(String pkg){android.view.inputmethod.InputMethodManager manager=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);for(android.view.inputmethod.InputMethodInfo input:manager.getInputMethodList())if(pkg.equals(input.getPackageName()))return true;return false;} private String appName(String pkg){try{return getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(pkg,0)).toString();}catch(Exception e){return pkg;}}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i!=null&&ACTION_LOCK.equals(i.getAction()))lock();else if(i!=null&&ACTION_HOME.equals(i.getAction()))goHome();else if(i!=null&&ACTION_SESSION.equals(i.getAction()))startSession(i.getStringExtra("pkg"),i.getIntExtra("minutes",5));else if(i!=null&&ACTION_FOREGROUND.equals(i.getAction()))acceptForeground(i.getStringExtra("pkg"));showCoinBadge();return START_STICKY;}
 private void lock(){DevicePolicyManager d=getSystemService(DevicePolicyManager.class);ComponentName a=new ComponentName(this,FocusAdminReceiver.class);if(d.isAdminActive(a))d.lockNow();else{Toast.makeText(this,"需要先开启锁屏权限，已返回主屏幕",Toast.LENGTH_LONG).show();goHome();}}
 @Override public void onTaskRemoved(Intent root){AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);PendingIntent p=PendingIntent.getBroadcast(this,91,new Intent(this,BootReceiver.class).setAction("com.focuscoins.RESTART"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);a.setAndAllowWhileIdle(AlarmManager.ELAPSED_REALTIME_WAKEUP,SystemClock.elapsedRealtime()+2000,p);super.onTaskRemoved(root);}
 @Override public void onDestroy(){getSharedPreferences(MainActivity.PREFS,0).edit().putBoolean(STATE,false).apply();try{unregisterReceiver(receiver);}catch(Exception ignored){}handler.removeCallbacksAndMessages(null);WindowManager wm=getSystemService(WindowManager.class);if(overlay!=null){try{wm.removeView(overlay);}catch(Exception ignored){}overlay=null;}if(coinBadge!=null){try{wm.removeView(coinBadge);}catch(Exception ignored){}coinBadge=null;}if(dailyIsland!=null){try{wm.removeView(dailyIsland);}catch(Exception ignored){}dailyIsland=null;}super.onDestroy();} @Override public IBinder onBind(Intent i){return null;}
}
